"use client";

import Image from "next/image";
import { useRef, useEffect } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import TransferCard from "./TransferCard";

gsap.registerPlugin(ScrollTrigger);

export default function MembershipJourney() {
  const section = useRef(null);
  const card = useRef(null);
  const content = useRef(null);

  useEffect(() => {
    const ctx = gsap.context(() => {
      gsap.fromTo(
        card.current,
        {
          x: -180,
          rotation: -18,
          scale: 0.9,
        },
        {
          x: 180,
          rotation: 15,
          scale: 1,
          ease: "none",
          scrollTrigger: {
            trigger: section.current,
            start: "top center",
            end: "bottom center",
            scrub: true,
          },
        }
      );

      gsap.from(content.current, {
        opacity: 0,
        y: 80,
        duration: 1,
        scrollTrigger: {
          trigger: section.current,
          start: "top 60%",
        },
      });
    });

    return () => ctx.revert();
  }, []);

  return (
    <section
      ref={section}
      className="relative h-screen flex items-center justify-center overflow-hidden"
    >
      {/* Background */}

      <Image
        src="/members-bg.webp"
        fill
        alt=""
        className="object-cover"
      />

      {/* Overlay */}

      <div className="absolute inset-0 bg-black/60" />

      <> 
      < TransferCard />
    
      </>

      {/* Content */}

      <div
        ref={content}
        className="relative z-10 text-center text-white max-w-2xl px-6"
      >
        <span className="uppercase tracking-[5px] text-sky-300">
          Membership
        </span>

        <h2 className="mt-4 text-6xl font-bold">
          Become a Member Today
        </h2>

        <p className="mt-6 text-lg text-gray-200 leading-8">
          Join thousands of members building wealth through
          secure savings, affordable loans, and investment
          opportunities with YPA Wealth Depot SACCO.
        </p>

        <button className="mt-10 rounded-full bg-sky-500 hover:bg-sky-600 px-10 py-4 text-lg font-semibold transition">
          Join Us
        </button>
      </div>
    </section>
  );
}